import ajax from "@/utils/ajax";
import { Message, Modal } from "@arco-design/web-react";
import { action, computed, observable, makeObservable } from "mobx";
import { dynamicCreateModule } from "@/environments/hoc";
import app from "./app";
import { moduleStore } from "react-converter-code";
import { ReactNode } from "react";
import _ from "lodash";
import dayjs from "dayjs";
import { addCSS, asyncAwaitFunction, getUuid } from "@/utils";


export interface MenuItem {
    id: string;
    path: string;
    paths?: string;
    parentId?: string;
    pageId?: string;
    isActive?: 0 | 1;
    type: 'directory' | 'menu';
    name: string;
    children: MenuItem[];
}

class PageStore {
    [x: string]: any;

    @observable isActive = false;
    @action
    setIsActive = (bool) => {
        this.isActive = bool;
    }

    loading = false;
    /**
     * 更新页面状态
     */
    updateIsActive = asyncAwaitFunction(async () => {
        if(this.isActive){
            await ajax.post('/apijson/put', {
                "Menu": { "isActive": 0, id: this.menu.id }
            })
        }else {
            await ajax.post('/apijson/put', {
                "Menu": { "isActive": 1, id: this.menu.id }
            })
        }
        this.setIsActive(!this.isActive);
        Message.success("路由状态更新成功");
    })

    menu: MenuItem;
    setMenu = (item: MenuItem) => {
        this.menu = item;
        this.isActive = item.isActive == 1;
    }

    @observable render = null;
    @action setRender = () => {
        this.render = this.jsxRender? dynamicCreateModule(this.jsxRender) : null;
    }


    constructor() {
        makeObservable(this);
    }


    @computed get updateTime(){
        return dayjs(this.updatedAt || 0).format("YYYY-MM-DD HH:mm:ss")
    }

    updateData(data){
        _.assign(this, data);
        this.setRender();
    }
}

class Store {
    pages: Record<string, PageStore> = {};
    addPage = async (data) => {
        const page = this.pages[data.id];
        page.updateData(data);
        
        this.pages[data.id] = page;
    }

    getPageList = () => {
        const ids = this.menus.map((o) => {
            if(o.type === "menu" && o.pageId){
                this.pages[o.pageId]= this.pages[o.pageId] || new PageStore();
                this.pages[o.pageId].setMenu(o);
            }
            return o.pageId;
        }).filter((o) => o);
        if(!ids.length) return;
        ajax.post('/apijson/get', {
            "Page[]": {
                "count": 0,
                "Page": {
                    "id{}": ids,
                    "@column": ["id","title", "type", "description", "status","coverImage","pageTitle", "userId", "extraInfo", "jsxRender", "updatedAt"].join(','),
                }
            }
        }).then(async (res) => {
            if(Array.isArray(res.Page)){
                for (const item of res.Page) {
                    // console.log('item', item)
                    if(item.extraInfo) {
                        item.extraInfo = JSON.parse(item.extraInfo);
                        // const { components, cssStr } = item.extraInfo;
                        // if(components && Array.isArray(components)){
                        //     await moduleStore.syncModuleIds(components);
                        //   }
                        //   // console.log('data', data, data.cssStr)
                        //   if(cssStr){
                        //       addCSS(cssStr, item.id);
                        // }
                    }
                    this.addPage(item);

                }
            }
        })
    }

    @observable menus:MenuItem[] = [];
    @action
    setMenus = (list) => {
        this.menus = list;
        this.getPageList();
    }

    getMenuList = () => {
        ajax.post('/apijson/get', {
            "Menu[]": {
                "count": 0,
                "Menu": {
                    "@order": "sort+"
                }
            }
        }).then((res) => {
            this.setMenus(res.Menu)
        })
    }

    updateMenu = (params: Partial<MenuItem>) => {

    }

    createPage = async (params) => {
        await ajax.post('/apijson/post', {
            "Page": {
                id: params.pageId,
                appId: app.appId,
                platform: app.platform,
                title: params.name,
            }
        })
    }

    saveMenu = async (params: Partial<MenuItem>) => {
        if(params.id){
            const data = {
                "Menu": {
                    id: params.id,
                    name: params.name,
                    path: params.path,
                },
            }
            if(params.type === "menu" && params.pageId){
                data['Page'] = { id: params.pageId, title: params.name }
            }
            // 更新路由
            return ajax.post('/apijson/put', data).then(() => {
                Message.success({
                    content: '更新成功',
                });
                this.getMenuList();
            })
        }
        if(params.type === "menu"){ // 如果是菜单创建新的页面
            params.pageId = getUuid();
            // 先新增页面
            await this.createPage(params);
        }
        return ajax.post('/apijson/post', {
            "Menu": {
                ...params,
                "sort": Date.now()/1000,
                "classId": app.appId,
            },
        }).then(async (res) => {
            Message.success({
                content: '新增成功',
            });
            this.getMenuList();
        })
    }


    /**
     * 克隆路由
     */
    copyNode = (node) => {
        return ajax.post('/apijson/get', {
            "Menu": { id: node.id },
            "Page": { id: node.pageId}
        }).then(async (res) => {
            const pageId = `${app.appId}-${getUuid('hash')}`;
            const name = `${node.name} copy`;
            await ajax.post('/apijson/post', {
                "Page": {
                    ...res.Page,
                    id: pageId,
                }
            })
            ajax.post("/apijson/post", {
                "Menu": {
                    ..._.omit(res.Menu, ['id']),
                    pageId,
                    name,
                    path: `${node.path}_copy`,
                },
            }).then(() => {
                Message.success("复制成功")
                this.getMenuList();
            })
        })

    }

    /**
     * 删除路由
     */
    deleteNode = (menu: MenuItem) => {
        if(menu.children && menu.children.length){
            return Message.warning("请先删除当前目录下接口或目录等信息")
        }
        Modal.confirm({
            title: `请确认删除【${menu.name}】`,
            onOk: () => {
                let params = { "Menu": { id: menu.id } }
                if(menu.type === "menu") params["Page"] = { id: menu.pageId };
                ajax.post("/apijson/delete", params).then((res) => {
                    Message.success("删除成功");
                    this.getMenuList();
                })
            }
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store;